    var body:some View {
        VStack(spacing:0){
            HStack {VStack(alignment:.leading,spacing:5){Text("Train · Fine-tuning").font(.title2.weight(.semibold));Text(context.authoredName).font(.caption).foregroundStyle(MLTheme.muted)};Spacer();Button("Close",action:close).buttonStyle(FlatButtonStyle()).keyboardShortcut(.cancelAction)}.padding(20)
            if !context.isCurrent {Text("The original selection changed. This draft is retained for reference; it cannot be applied. Close and reopen the original component to edit it.").font(.caption).foregroundStyle(MLTheme.rose).textSelection(.enabled).padding(.horizontal,20).padding(.bottom,10)}
            Divider()
            HStack(spacing:0){
                VStack(alignment:.leading,spacing:5){ForEach(sections,id:\.self){name in Button{section=name}label:{Text(name).frame(maxWidth:.infinity,alignment:.leading).padding(10).background(section==name ? MLTheme.rose.opacity(0.16):Color.clear).contentShape(Rectangle())}.buttonStyle(.plain)};Spacer()}.padding(12).frame(width:220)
                Divider()
                ScrollView {VStack(alignment:.leading,spacing:18){Text(section).font(.title3.weight(.semibold));content}.padding(24).frame(maxWidth:.infinity,alignment:.leading)}
            }
            Divider()
            VStack(alignment:.leading,spacing:10){
                Text(!message.isEmpty ? message:store.isBusy ? store.status:validated ? "Prepared inputs inspected · no training run.":"Draft · validate before applying").font(.caption).foregroundStyle(!message.isEmpty ? MLTheme.rose:MLTheme.muted).textSelection(.enabled)
                HStack {Button("Revert",action:load).buttonStyle(FlatButtonStyle());Spacer();Text("Apply saves settings. Run Flow starts training.").font(.caption).foregroundStyle(MLTheme.muted);if store.isBusy || host.isInspectingFineTuning(address) {Button("Cancel inspection"){host.cancelFineTuningInspection(address)}.buttonStyle(FlatButtonStyle())}else{Button("Validate & inspect",action:validate).buttonStyle(FlatButtonStyle()).disabled(!context.isCurrent || !numeric.isEmpty || host.hasActiveOperation)};Button("Apply",action:apply).buttonStyle(FlatButtonStyle(prominent:true)).disabled(!context.isCurrent || !validated || !numeric.isEmpty)}
            }.padding(16)
        }.frame(minWidth:800,idealWidth:1000,minHeight:610,idealHeight:760).background(MLTheme.background)
        .onAppear{load();registerDiscard({discard()}, {!closing && (dirty)})}
        .onDisappear{discard()}
        .onChange(of:config){_,_ in report()}
        .onChange(of:store.isBusy){_,busy in if !busy {report()}}
    }
    @ViewBuilder private var content:some View {
        switch section {
        case "Model & source":
            group("Connected model") {Text(source?.metadata["architecture"]?.stringValue?.uppercased() ?? "Load the connected causal model first.").font(.headline);Text("Base · "+(source?.identity ?? "Unavailable")).font(.caption.monospaced()).textSelection(.enabled);Text("Tokenizer and actual parameter inventory follow this verified model. No implicit model download or repository code.").font(.caption).foregroundStyle(MLTheme.muted)}
            group("Task capabilities") {Text("Reviewed GPT-2 / Llama causal training · Full, selected groups and supported LoRA projections. CPU continuation and Apple GPU weights reuse have different guarantees.");Text("Data → Train → Generate / Evaluate → Save remains on the existing canvas.").font(.caption).foregroundStyle(MLTheme.muted)}
        case "Data & loss":
