                if fine["exampleFormat"] == .string("promptResponse") {column("Prompt column","promptColumn");column("Response column","responseColumn");Text("Separator · use \\n for a newline").font(.caption);TextField("Separator",text:Binding(get:{(fine["separator"]?.stringValue ?? "\n").replacingOccurrences(of:"\n",with:"\\n")},set:{set("separator",.string($0.replacingOccurrences(of:"\\n",with:"\n")))})).flatField();choice("Loss coverage","lossCoverage",[("response","Response tokens only"),("all","Full example")]);Text("Prompt and padding are masked when scoring responses. Too-long examples are rejected; responses are never silently cut away.").font(.caption).foregroundStyle(MLTheme.muted)}else{column("Text column","textColumn");number("Window stride","stride",1,131071)}
                number("Maximum tokens","maximumTokens",2,131072);flag("Append end-of-sequence","appendEOS")
            }
            if let preview=store.fineTuningPreview {
                group("Prepared sample · explicit inspection") {Text("Training \(preview["trainingWindows"]?.integerValue ?? 0) windows / \(preview["trainingScoredTokens"]?.integerValue ?? 0) scored tokens\nValidation \(preview["validationWindows"]?.integerValue ?? 0) windows / \(preview["validationScoredTokens"]?.integerValue ?? 0) scored tokens").font(.caption)
                    if case .array(let tokens)=preview["sampleTokens"],case .array(let masks)=preview["sampleScored"] {Text(tokens.enumerated().map{i,token in (i==0 || masks.indices.contains(i) && masks[i] == .bool(false) ? "[context] ":"[score] ")+(token.stringValue ?? "?")}.joined(separator:"\n")).font(.caption.monospaced()).textSelection(.enabled).frame(maxWidth:.infinity,alignment:.leading).padding(12).background(MLTheme.panel).overlay(Rectangle().stroke(MLTheme.rule))}
                    Text("First window · at most 512 displayed tokens; not the training population. Preview may refer to the last inspected draft.").font(.caption).foregroundStyle(MLTheme.muted)
                }
            }
        case "Trainable weights":
            group("Training method") {choice("Trainable weights","mode",[("full","Full model"),("selected","Selected layers"),("lora","LoRA adapter")].filter{mode in if case .array(let modes)=inventory["supportedModes"]{return modes.contains(.string(mode.0))};return mode.0 != "lora"});if store.fineTuningInspectedConfiguration==config,let preview=store.fineTuningPreview,let count=preview["trainableParameters"]?.integerValue {Text("Inspected draft · \(count.formatted()) trainable / \(preview["totalParameters"]?.integerValue?.formatted() ?? "?") total · estimated resident bytes \(preview["estimatedResidentBytes"]?.integerValue?.formatted() ?? "?")").font(.caption);Text(preview["gradientCheck"]?.stringValue ?? "").font(.caption).foregroundStyle(MLTheme.muted)};if let total=inventory["totalParameters"]?.integerValue {Text("\(total.formatted()) actual base parameters · linked groups remain linked").font(.caption).foregroundStyle(MLTheme.muted)}}
            if fine["mode"] == .string("lora") {group("Adapter settings") {number("Rank","rank",1,1024);number("Scale (alpha)","alpha",0.00001,1_000_000,integer:false);number("Dropout","dropout",0,0.999999,integer:false);choice("Bias","bias",[("none","Frozen"),("lora_only","Adapter layers"),("all","All bias values")])}}
            if fine["mode"] != .string("full") {group(fine["mode"] == .string("lora") ? "Target projections":"Actual parameter groups") {TextField("Find module or layer…",text:$search).flatField();HStack{Button("Select compatible"){set(fine["mode"] == .string("lora") ? "targets":"groups",.array(rows(fine["mode"] == .string("lora") ? "targets":"groups").compactMap{$0["id"]}))}.buttonStyle(FlatButtonStyle());Button("Clear"){set(fine["mode"] == .string("lora") ? "targets":"groups",.array([]))}.buttonStyle(FlatButtonStyle())};selections(fine["mode"] == .string("lora") ? "targets":"groups")}}
            if fine["mode"] == .string("lora") {group("Additional independent modules") {selections("groups",selection:"additionalModules",independent:true);Text("Tied groups and modules overlapping the selected LoRA projections are refused by validation.").font(.caption).foregroundStyle(MLTheme.muted)}}
        case "Optimization":
            group("Training budget") {number("Target total epochs","epochs",1,10000,scope:"runSetup");number("Microbatch windows","batchSize",1,1024,scope:"runSetup");number("Gradient accumulation","accumulation",1,1024);number("Seed","seed",0,4294967295,scope:"runSetup")}
            group("Shared optimizer") {optimizerControls}
            group("Shared schedule") {schedulerControls}
        case "Validation & selection":
            group("Inference model selection") {choice("Selected inference weights","modelSelection",[("finalEpoch","Final epoch"),("bestValidation","Best Validation")],scope:"trainingControl");flag("Enable early stopping","enabled",scope:"earlyStopping");number("Patience in completed epochs","patience",1,10000,scope:"earlyStopping");number("Minimum improvement","minimumImprovement",0,1_000_000,integer:false,scope:"earlyStopping");Text("Validation performs no updates. Test is reserved for explicit Evaluate, never model selection. Inference selection is separate from the latest resume boundary.").font(.caption).foregroundStyle(MLTheme.muted)}
        case "Compute & limits":
            group("Qualified execution") {choice("Learning device","device",[("auto","Automatic · resolve on this Mac"),("cpu","CPU reference"),("mps","Apple GPU · MPS")],scope:"runSetup");flag("Recompute activations during backward","activationCheckpointing");Text("Float32 · explicit model-matched adapter. Activation recomputation trades compute for memory; it is not a retained training checkpoint. Model/source/result size and project CPU/RSS/time/storage limits remain enforced.").font(.caption).foregroundStyle(MLTheme.muted)}
        default:
            group("Starting state") {choice("Start operation","startMode",[("base","New from loaded model"),("weights","Reuse recorded inference weights · fresh optimizer"),("resume","Resume verified CPU training boundary")]);if fine["startMode"] != .string("base") {let records=store.trainingRecords.filter{$0.address==address};FlatChoiceControl(title:"Recorded training run",selection:fine["resumeRecord"]?.stringValue ?? "",options:records.map{.init(id:$0.id,title:String($0.id.prefix(8))+" · "+$0.finishedAt.formatted())}+(fine["startMode"] == .string("resume") ? store.fineTuningRecoveries.filter{$0.address==address}.map{.init(id:$0.id,title:"Recover "+String($0.id.prefix(8))+" · epoch "+String($0.epochs.max() ?? 0))}:[])+(fine["startMode"] == .string("resume") ? store.importedResumes.map{.init(id:$0.id,title:"Imported "+String($0.id.prefix(8))+" · epoch "+String($0.completedEpoch))}:[])){set("resumeRecord",.string($0))};if fine["startMode"] == .string("resume") {Button("Import CPU resume package…"){context.setNumericPending(origin:context.numericOrigin(key:"fineTuningDraft"),key:"fineTuningDraft",pending:false);host.chooseFineTuningResumePackage(address);report()}.buttonStyle(FlatButtonStyle()).disabled(store.isBusy);number("Retained epoch · 0 selects latest","resumeEpoch",0,10000);Text("Exact resume requires the original base/tokenizer, data, runtime, settings and schedule horizon. MPS runs support weight reuse only. Original run evidence remains immutable.").font(.caption).foregroundStyle(MLTheme.muted)}}}
            group("Completed-epoch retention") {number("Completed boundaries to keep","checkpointCount",0,10);number("Checkpoint storage bytes","checkpointBytes",1,8_000_000_000);Text("Zero keeps the legacy terminal-only behavior. Pause commits an epoch. Stop now preserves committed retained epochs; terminal-only jobs have no intermediate recovery. Required references are never silently removed to fit a budget.").font(.caption).foregroundStyle(MLTheme.muted)}
        }
    }
    private func group<C:View>(_ title:String,@ViewBuilder content:()->C)->some View {VStack(alignment:.leading,spacing:12){Text(title).font(.headline);content()}.padding(16).frame(maxWidth:.infinity,alignment:.leading).background(MLTheme.panel).overlay(Rectangle().stroke(MLTheme.rule))}
    private func object(_ value:JSONValue?)->[String:JSONValue] {if case .object(let fields)=value{return fields};return [:]}
    private func fields(_ scope:String)->[String:JSONValue] {switch scope{case "runSetup":return run;case "trainingControl":return control;case "earlyStopping":return object(control["earlyStopping"]);case "optimizer":return object(object(config["optimizer"])["config"]);case "scheduler":return object(object(config["scheduler"])["config"]);default:return fine}}
    private func set(_ key:String,_ value:JSONValue,scope:String="fine") {var next=fields(scope);next[key]=value;switch scope{case "runSetup":config["runSetup"] = .object(next);case "trainingControl":var r=run;r["trainingControl"] = .object(next);config["runSetup"] = .object(r);case "earlyStopping":var c=control;c["earlyStopping"] = .object(next);setControl(c);case "optimizer","scheduler":var recipe=object(config[scope]);recipe["config"] = .object(next);config[scope] = .object(recipe);default:config["fineTuning"] = .object(next)}}
    private func setControl(_ value:[String:JSONValue]) {var r=run;r["trainingControl"] = .object(value);config["runSetup"] = .object(r)}
    private func choice(_ title:String,_ key:String,_ choices:[(String,String)],scope:String="fine")->some View {VStack(alignment:.leading,spacing:5){Text(title).font(.caption);FlatChoiceControl(title:title,selection:fields(scope)[key]?.stringValue ?? "",options:choices.map{.init(id:$0.0,title:$0.1)}){set(key,.string($0),scope:scope)}}}
    private func flag(_ title:String,_ key:String,scope:String="fine")->some View {Toggle(title,isOn:Binding(get:{fields(scope)[key] == .bool(true)},set:{set(key,.bool($0),scope:scope)})).toggleStyle(FileInputCheckboxStyle(tint:MLTheme.rose)).font(.caption)}
    private func number(_ title:String,_ key:String,_ min:Double,_ max:Double,integer:Bool=true,scope:String="fine")->some View {let origin=identity.uuidString+scope+key;return VStack(alignment:.leading,spacing:5){Text(title).font(.caption);BoundedNumberField(title:title,value:integer ? .wholeDisplay(fields(scope)[key]?.doubleValue ?? min):.decimal(fields(scope)[key]?.doubleValue ?? min),domain:integer ? .integer(minimum:min,maximum:max):.decimal(minimum:min,maximum:max),origin:origin,currentOrigin:{closing ? nil:identity.uuidString+scope+key},onDraftChange:{_,dirty in if dirty{numeric.insert(origin)}else{numeric.remove(origin)};report()}){candidate in switch candidate{case .integer(let n):set(key,.integer(n),scope:scope);case .decimal(let n):set(key,.number(n),scope:scope)};return true}}}
    private func column(_ title:String,_ key:String)->some View {let names=host.sourceProvider.recordedSchema(for:address,in:host.owner.document,inputPort:"training").filter{$0.dtype=="string"}.map(\.name);return VStack(alignment:.leading,spacing:5){Text(title).font(.caption);if names.isEmpty {TextField(title,text:Binding(get:{fine[key]?.stringValue ?? ""},set:{set(key,.string($0))})).flatField()}else{FlatChoiceControl(title:title,selection:fine[key]?.stringValue ?? "",options:names.map{.init(id:$0,title:$0)}){set(key,.string($0))}}}}
    private func rows(_ key:String)->[[String:JSONValue]] {if case .array(let values)=inventory[key]{return values.compactMap{if case .object(let row)=$0{return row};return nil}};return []}
    private func names(_ key:String)->[String] {if case .array(let values)=fine[key]{return values.compactMap(\.stringValue)};return []}
    private func selections(_ key:String,selection:String?=nil,independent:Bool=false)->some View {let selected=selection ?? key;let all=rows(key).filter{(!independent || $0["tied"] != .bool(true)) && (search.isEmpty || String(describing:$0).localizedCaseInsensitiveContains(search))};return LazyVStack(alignment:.leading,spacing:8){ForEach(Array(all.enumerated()),id:\.offset){_,row in if let id=row["id"]?.stringValue {HStack{Toggle(row["title"]?.stringValue ?? id,isOn:Binding(get:{names(selected).contains(id)},set:{on in var values=names(selected);values.removeAll{$0==id};if on{values.append(id)};set(selected,.array(values.map(JSONValue.string)))})).toggleStyle(FileInputCheckboxStyle(tint:MLTheme.rose));Spacer();Text(row["tied"] == .bool(true) ? "Linked":row["count"]?.integerValue?.formatted() ?? "").foregroundStyle(MLTheme.muted)}.font(.caption);Divider()}}}}
    @ViewBuilder private var optimizerControls:some View {let recipe=object(config["optimizer"]);let id=recipe["componentID"]?.stringValue ?? "optimizer_adamw";FlatChoiceControl(title:"Optimizer",selection:id,options:OptimizerConfiguration.componentIDs.sorted().map{.init(id:$0,title:$0.replacingOccurrences(of:"optimizer_",with:""))}){if let c=try? OptimizerConfiguration(componentID:$0,values:[:]){config["optimizer"]=c.recipeValue}};ForEach(fields("optimizer").keys.sorted(),id:\.self){key in if case .bool=fields("optimizer")[key]{flag(key,key,scope:"optimizer")}else{number(key,key,key=="eps" ? OptimizerConfiguration.epsilonMinimum:0,OptimizerConfiguration.scalarMaximum,integer:false,scope:"optimizer")}}}
    @ViewBuilder private var schedulerControls:some View {let recipe=object(config["scheduler"]);FlatChoiceControl(title:"Schedule",selection:recipe["componentID"]?.stringValue ?? "constant",options:[.init(id:"constant",title:"Constant learning rate")]+SchedulerConfiguration.componentIDs.sorted().map{.init(id:$0,title:$0.replacingOccurrences(of:"scheduler_",with:""))}){if $0=="constant"{config.removeValue(forKey:"scheduler")}else if let value=try? SchedulerConfiguration(componentID:$0,values:[:]){config["scheduler"]=value.recipeValue}};Text("Existing schedule controls remain tied to the canonical recipe and captured epoch/update horizon.").font(.caption).foregroundStyle(MLTheme.muted);ForEach(fields("scheduler").keys.sorted(),id:\.self){key in if let text=fields("scheduler")[key]?.stringValue {let choices=key=="metric" ? ["validation_loss"]:key=="mode" ? ["min","max"]:key=="threshold_mode" ? ["rel","abs"]:["cos","linear"];choice(key,key,choices.map{($0,$0)},scope:"scheduler")}else if case .bool=fields("scheduler")[key]{flag(key,key,scope:"scheduler")}else{number(key,key,0,1_000_000,integer:fields("scheduler")[key]?.integerValue != nil,scope:"scheduler")}}}
    private func load(){guard context.isCurrent else{return};host.cancelFineTuningInspection(address);original=context.configuration;config=original;var fine=object(config["fineTuning"]);var defaults=FineTuningConfiguration.expansionDefaults;defaults["checkpointCount"]=0;fine=defaults.merging(fine){_,old in old};config["fineTuning"] = .object(fine);if run["trainingControl"]==nil,let value=try? JSONDecoder().decode(JSONValue.self,from:JSONEncoder().encode(TrainingControlPolicy.factory)){setControl(object(value))};if config["optimizer"]==nil,let c=try? OptimizerConfiguration(componentID:"optimizer_adamw",values:["lr":run["learningRate"] ?? 0.001]){config["optimizer"]=c.recipeValue};baseline=config;numeric=[];tested=nil;message="";identity=UUID();report()}
    private func report(){context.setNumericPending(origin:context.numericOrigin(key:"fineTuningDraft"),key:"fineTuningDraft",pending:!closing && dirty)}
    private func validate(){guard context.isCurrent else{return};do{_=try FineTuningConfiguration(fine);var document=host.owner.document;guard let i=document.nodes.firstIndex(where:{$0.address==address})else{throw WorkflowArchiveError("Train was removed.")};document.nodes[i].payload = .train(config:config);try WorkflowCodec.validate(document);context.setNumericPending(origin:context.numericOrigin(key:"fineTuningDraft"),key:"fineTuningDraft",pending:false);tested=config;message="";store.clearFineTuningInspection();if !host.inspectFineTuning(address,draft:config){tested=nil;message=host.statusMessage;report()}}catch{message=error.localizedDescription}}
    private func apply(){guard validated else{return};context.setNumericPending(origin:context.numericOrigin(key:"fineTuningDraft"),key:"fineTuningDraft",pending:false);guard context.authority.configure(config,expected:original)else{message=context.statusMessage;report();return};closing=true;requestClose()}
    private func discard(){guard !closing else{return};closing=true;host.cancelFineTuningInspection(address);context.setNumericPending(origin:context.numericOrigin(key:"fineTuningDraft"),key:"fineTuningDraft",pending:false)}
    private func close(){requestClose()}
}
